func openTestGameBacklogStore(t *testing.T) *Store {
	t.Helper()
	dbPath := filepath.Join(t.TempDir(), "game-backlog.db")
	s, err := OpenWithContext(context.Background(), dbPath)
	if err != nil {
		t.Fatalf("open store: %v", err)
	}
	t.Cleanup(func() { s.Close() })
	return s
}

func countGameBacklogRows(t *testing.T, s *Store) int {
	t.Helper()
	var n int
	if err := s.DB().QueryRow(`SELECT COUNT(*) FROM game_backlog`).Scan(&n); err != nil {
		t.Fatalf("count game_backlog: %v", err)
	}
	return n
}

func isRFC3339UTC(s string) bool {
	if _, err := time.Parse(time.RFC3339, s); err != nil {
		return false
	}
	return strings.HasSuffix(s, "Z") || strings.Contains(s, "+00:00")
}

